import{_ as l,o as e,c as a,a5 as d}from"./chunks/framework.Bt0SrEfo.js";const b=JSON.parse('{"title":"Vite 为什么 dev 用 esbuild、prod 用 Rollup（双构建）？","description":"","frontmatter":{},"headers":[],"relativePath":"面试/Vite/3-dual_build.md","filePath":"面试/Vite/3-dual_build.md","lastUpdated":1790091846000}'),r={name:"面试/Vite/3-dual_build.md"};function i(o,t,s,n,p,u){return e(),a("div",null,[...t[0]||(t[0]=[d(`<h1 id="vite-为什么-dev-用-esbuild、prod-用-rollup-双构建" tabindex="-1">Vite 为什么 dev 用 esbuild、prod 用 Rollup（双构建）？ <a class="header-anchor" href="#vite-为什么-dev-用-esbuild、prod-用-rollup-双构建" aria-label="Permalink to &quot;Vite 为什么 dev 用 esbuild、prod 用 Rollup（双构建）？&quot;">​</a></h1><blockquote><p>📚 <strong>深度专题推荐</strong>：本文是关于「Vite 双构建策略」的精炼回答。如需了解 HMR 原理，建议阅读 <a href="/面试/Webpack/1-HMR">Vite HMR 原理</a>。</p></blockquote><hr><h2 id="一、vite-双构建策略" tabindex="-1">一、Vite 双构建策略 <a class="header-anchor" href="#一、vite-双构建策略" aria-label="Permalink to &quot;一、Vite 双构建策略&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npm run dev（开发环境）    →   esbuild（速度优先）</span></span>
<span class="line"><span>npm run build（生产环境）  →   Rollup（产物质量优先）</span></span></code></pre></div><hr><h2 id="二、dev-用-esbuild" tabindex="-1">二、Dev 用 esbuild <a class="header-anchor" href="#二、dev-用-esbuild" aria-label="Permalink to &quot;二、Dev 用 esbuild&quot;">​</a></h2><h3 id="原因" tabindex="-1">原因 <a class="header-anchor" href="#原因" aria-label="Permalink to &quot;原因&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>esbuild</th><th>Rollup</th></tr></thead><tbody><tr><td>速度</td><td><strong>极快</strong>（Go 机器码）</td><td>慢（JS）</td></tr><tr><td>代码分割</td><td>弱</td><td>强</td></tr><tr><td>Tree-shaking</td><td>一般</td><td>优秀</td></tr><tr><td>适用场景</td><td>dev transform</td><td>prod build</td></tr></tbody></table><h3 id="dev-阶段-esbuild-做什么" tabindex="-1">Dev 阶段 esbuild 做什么？ <a class="header-anchor" href="#dev-阶段-esbuild-做什么" aria-label="Permalink to &quot;Dev 阶段 esbuild 做什么？&quot;">​</a></h3><ol><li><strong>依赖预构建</strong>（最关键）</li><li><strong>TypeScript / JSX 转译</strong>（去掉类型、不做类型检查）</li><li><strong>CSS 处理</strong>（部分）</li><li><strong>CommonJS → ESM</strong></li></ol><h3 id="dev-不需要完美产物的理由" tabindex="-1">Dev 不需要完美产物的理由 <a class="header-anchor" href="#dev-不需要完美产物的理由" aria-label="Permalink to &quot;Dev 不需要完美产物的理由&quot;">​</a></h3><ul><li>dev 产物只在浏览器跑一次，下次改代码就重建</li><li><strong>速度 &gt; 完美度</strong></li><li>浏览器对 dev 产物体积不敏感（gzip 前几 MB 完全 OK）</li></ul><hr><h2 id="三、prod-用-rollup" tabindex="-1">三、Prod 用 Rollup <a class="header-anchor" href="#三、prod-用-rollup" aria-label="Permalink to &quot;三、Prod 用 Rollup&quot;">​</a></h2><h3 id="原因-1" tabindex="-1">原因 <a class="header-anchor" href="#原因-1" aria-label="Permalink to &quot;原因&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>esbuild</th><th>Rollup</th></tr></thead><tbody><tr><td>产物质量</td><td>一般（未优化）</td><td>优秀</td></tr><tr><td>Tree-shaking</td><td>实验性</td><td><strong>业界最强</strong></td></tr><tr><td>代码分割</td><td>弱</td><td>强</td></tr><tr><td>兼容性</td><td>部分 ES 高级语法没处理</td><td>完善</td></tr><tr><td>生态插件</td><td>较少</td><td><strong>极其丰富</strong></td></tr></tbody></table><h3 id="rollup-在-prod-阶段做什么" tabindex="-1">Rollup 在 prod 阶段做什么？ <a class="header-anchor" href="#rollup-在-prod-阶段做什么" aria-label="Permalink to &quot;Rollup 在 prod 阶段做什么？&quot;">​</a></h3><ol><li><strong>完整的代码分割</strong>（vendor 拆分、动态 import、chunk 优化）</li><li><strong>深度 tree-shaking</strong>（DCE 算法）</li><li><strong>CSS 提取 / 压缩</strong></li><li><strong>资源 hash / 文件名优化</strong></li><li><strong>多页面 / 库模式打包</strong></li><li><strong>完整的浏览器兼容性处理</strong></li></ol><h3 id="生产产物要求" tabindex="-1">生产产物要求 <a class="header-anchor" href="#生产产物要求" aria-label="Permalink to &quot;生产产物要求&quot;">​</a></h3><ul><li>体积小（gzip 前）</li><li>加载快（preload、prefetch、HTTP/2 push）</li><li>缓存友好（hash 文件名、长缓存）</li><li>兼容目标浏览器（es5 / es2015）</li></ul><hr><h2 id="四、为什么不用-esbuild-做-prod" tabindex="-1">四、为什么不用 esbuild 做 prod？ <a class="header-anchor" href="#四、为什么不用-esbuild-做-prod" aria-label="Permalink to &quot;四、为什么不用 esbuild 做 prod？&quot;">​</a></h2><h3 id="evan-you-的官方解释" tabindex="-1">Evan You 的官方解释 <a class="header-anchor" href="#evan-you-的官方解释" aria-label="Permalink to &quot;Evan You 的官方解释&quot;">​</a></h3><blockquote><p>&quot;esbuild 的 production build 还不成熟，主要在两个方面：</p><ol><li>Type stripping 不完整（TypeScript 的 enum / namespace 等不处理）</li><li>浏览器兼容性、产物优化、tree-shaking 都还不够&quot;</li></ol></blockquote><h3 id="实际原因" tabindex="-1">实际原因 <a class="header-anchor" href="#实际原因" aria-label="Permalink to &quot;实际原因&quot;">​</a></h3><ol><li><p><strong>TypeScript 支持不完整</strong></p><ul><li>esbuild 只去类型，不做类型检查</li><li>enum / namespace 转换有问题</li></ul></li><li><p><strong>CSS 处理弱</strong></p><ul><li>复杂的 PostCSS 插件链不支持</li><li>CSS Modules / 预处理器兼容性差</li></ul></li><li><p><strong>产物优化不够</strong></p><ul><li>tree-shaking 实验性</li><li>代码分割策略单一</li></ul></li><li><p><strong>生态</strong></p><ul><li>Rollup 插件生态极其丰富（Vite 直接复用）</li><li>esbuild 插件需要自己写</li></ul></li></ol><hr><h2 id="五、未来的可能性" tabindex="-1">五、未来的可能性 <a class="header-anchor" href="#五、未来的可能性" aria-label="Permalink to &quot;五、未来的可能性&quot;">​</a></h2><p>Vite 团队一直在尝试用 esbuild 做 prod build（性能更优）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2023  Vite 5：prod 仍用 Rollup</span></span>
<span class="line"><span>2024  Vite 6/7：尝试 esbuild 做 prod，fallback 到 Rollup</span></span>
<span class="line"><span>未来   Rolldown（Rust 版的 Rollup）成熟后，可能替代 Rollup</span></span></code></pre></div><p><strong>Rolldown</strong> 是 Vite 团队用 Rust 重写的 Rollup，目标是同时具备 esbuild 的速度和 Rollup 的产物质量。</p><hr><h2 id="六、性能对比" tabindex="-1">六、性能对比 <a class="header-anchor" href="#六、性能对比" aria-label="Permalink to &quot;六、性能对比&quot;">​</a></h2><p>实测中型 Vue 项目（500 模块）：</p><table tabindex="0"><thead><tr><th>工具</th><th>dev 启动</th><th>prod 构建</th><th>产物体积</th></tr></thead><tbody><tr><td>Vite（esbuild dev + Rollup prod）</td><td><strong>0.4s</strong></td><td>28s</td><td>1.2MB</td></tr><tr><td>Webpack 5（全程自己）</td><td>28s</td><td>65s</td><td>1.4MB</td></tr><tr><td>假设 esbuild 全程</td><td>0.3s</td><td>8s</td><td>1.6MB（更大）</td></tr><tr><td>假设 Rollup 全程</td><td>18s</td><td>22s</td><td>1.1MB</td></tr></tbody></table><p><strong>结论</strong>：Vite 取了 dev 速度 + prod 产物质量的最佳平衡。</p><hr><h2 id="七、面试追问" tabindex="-1">七、面试追问 <a class="header-anchor" href="#七、面试追问" aria-label="Permalink to &quot;七、面试追问&quot;">​</a></h2><p><strong>Q：dev 用 esbuild，prod 用 Rollup，构建配置要写两套吗？</strong></p><p>A：<strong>不用</strong>。Vite 的 <code>vite.config.ts</code> 是统一的。dev 阶段 Vite 自动选择 esbuild，prod 阶段自动选择 Rollup。你只需要写一份配置。</p><p><strong>Q：Vite 为什么不用 Webpack 风格的「统一」构建？</strong></p><p>A：dev 和 prod 阶段的目标不同：</p><ul><li>dev：速度、实时反馈 → 牺牲产物质量</li><li>prod：产物质量、加载性能 → 牺牲构建速度</li></ul><p>强行统一 = 两者都做不好。</p><p><strong>Q：有没有可能 Vite 6 全部用 esbuild？</strong></p><p>A：短期内不会。esbuild 的 prod 能力还在追赶。等 esbuild 完善了 type stripping、tree-shaking、代码分割后，Vite 可能切换。<strong>Rolldown（Rust Rollup）</strong> 是另一个备选。</p><hr><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><ul><li><a href="https://cn.vitejs.dev/guide/why.html" target="_blank" rel="noreferrer">https://cn.vitejs.dev/guide/why.html</a></li><li><a href="https://rollupjs.org/" target="_blank" rel="noreferrer">https://rollupjs.org/</a></li><li><a href="https://rolldown.rs/" target="_blank" rel="noreferrer">https://rolldown.rs/</a></li></ul>`,50)])])}const c=l(r,[["render",i]]);export{b as __pageData,c as default};
